class DateTimeFormat:
    """
    A class for validating and formatting a datetime string. It uses a regular expression to match the format of the datetime string and then parses it into a `datetime` object, handling microseconds and timezone information appropriately.

    Parameters:
        self (DateTimeFormat): The instance of the `DateTimeFormat` class.
        value (typing.Any): The input value that needs to be validated as a datetime string.

    Returns:
        datetime.datetime: A valid datetime object parsed from the input string, with microseconds and timezone information if present.

    Raises:
        ValidationError: If the input does not match the expected format or is not a real datetime. The error message will indicate whether it was due to an invalid format or an invalid datetime value.

    Example Usage:
        date_time_format = DateTimeFormat()
        try:
            validated_datetime = date_time_format.validate("2023-10-15T14:30:00Z")  # Valid ISO 8601 format with timezone 'Z'
        except ValidationError as e:
            print(e)  # Outputs the error message related to either invalid format or invalid datetime value.
    """
    errors = {'format': 'Must be a valid datetime format.', 'invalid': 'Must be a real datetime.'}
    def validate(self, value: typing.Any) -> datetime.datetime:
        match = DATETIME_REGEX.match(value)
        if not match:
            raise self.validation_error("format")

        groups = match.groupdict()
        if groups["microsecond"]:
            groups["microsecond"] = groups["microsecond"].ljust(6, "0")

        tzinfo_str = groups.pop("tzinfo")
        if tzinfo_str == "Z":
            tzinfo = datetime.timezone.utc
        elif tzinfo_str is not None:
            offset_mins = int(tzinfo_str[-2:]) if len(tzinfo_str) > 3 else 0
            offset_hours = int(tzinfo_str[1:3])
            delta = datetime.timedelta(hours=offset_hours, minutes=offset_mins)
            if tzinfo_str[0] == "-":
                delta = -delta
            tzinfo = datetime.timezone(delta)
        else:
            tzinfo = None

        kwargs = {k: int(v) for k, v in groups.items() if v is not None}
        try:
            return datetime.datetime(**kwargs, tzinfo=tzinfo)  # type: ignore
        except ValueError:
            raise self.validation_error("invalid")
