class Schema:
    """
    Initializes a `Schema` instance. This function allows for initialization via positional arguments or keyword arguments. If initialized with positional arguments, it expects exactly one argument which must be a dictionary or an object with attributes corresponding to the fields defined in the schema. It then sets these attributes on the schema instance. If initialized with keyword arguments, it validates each provided argument against its respective field definition and raises a `TypeError` if any validation fails. Additionally, it handles invalid keyword arguments by raising a `TypeError`.

    Parameters:
        *args (tuple): A tuple of positional arguments. The only valid use case is providing one dictionary or object as the sole argument.
        **kwargs (dict): A dictionary of keyword arguments where keys are field names and values are the corresponding values to be set on the schema instance.

    Raises:
        AssertionError: If the number of positional arguments is not exactly one, if any keyword arguments are provided, or if there's an issue with the type or structure of the provided argument(s).
        TypeError: If a keyword argument does not correspond to a defined field in the schema, if validation fails for any provided keyword argument, or if an invalid keyword argument is provided.

    Returns:
        None

    Example usage:
        # Example with positional arguments (not recommended)
        schema = Schema({'name': 'string', 'age': 30})

        # Example with keyword arguments
        schema = Schema(name='string', age=30)
    """
    fields: typing.Dict[str, Field] = {}

    def __init__(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        if args:
            assert len(args) == 1
            assert not kwargs
            item = args[0]
            if isinstance(item, dict):
                for key in self.fields.keys():
                    if key in item:
                        setattr(self, key, item[key])
            else:
                for key in self.fields.keys():
                    if hasattr(item, key):
                        setattr(self, key, getattr(item, key))
            return

        for key, schema in self.fields.items():
            if key in kwargs:
                value = kwargs.pop(key)
                value, error = schema.validate_or_error(value)
                if error:
                    class_name = self.__class__.__name__
                    error_text = " ".join(
                        [message.text for message in error.messages()]
                    )
                    message = (
                        f"Invalid argument {key!r} for {class_name}(). {error_text}"
                    )
                    raise TypeError(message)
                setattr(self, key, value)
            elif schema.has_default():
                setattr(self, key, schema.get_default_value())

        if kwargs:
            key = list(kwargs.keys())[0]
            class_name = self.__class__.__name__
            message = f"{key!r} is an invalid keyword argument for {class_name}()."
            raise TypeError(message)

    def validate_or_error(
        cls: typing.Type["Schema"], value: typing.Any, *, strict: bool = False
    ) -> ValidationResult:
        """
        Validates the given `value` against the provided `Schema` class and returns a `ValidationResult`.

        Parameters:
            cls (typing.Type["Schema"]): The schema class to validate against.
            value (typing.Any): The value to be validated.
            strict (bool, optional): Whether to enforce strict validation. Defaults to False.

        Returns:
            ValidationResult: An object containing the validated `value` and any encountered `error`.

        Raises:
            None

        Usage:
            result = validate_or_error(SchemaClass, input_value)
        """
        try:
            value = cls.validate(value, strict=strict)
        except ValidationError as error:
            return ValidationResult(value=None, error=error)
        return ValidationResult(value=value, error=None)
